                    <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                               @bind:after="OnDateChanged" />
                    <ValidationMessage For="() => Model.AppointmentDate" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="timeslot">Time Slot</label>
                    <InputSelect id="timeslot" class="form-select" @bind-Value="Model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.TimeSlot" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="reason">Reason for Visit</label>
                    <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.ReasonForVisit" />
                    <ValidationMessage For="() => Model.ReasonForVisit" />
                </div>

                <div class="d-flex gap-2">
                    <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">Back</button>
                    <button type="submit" class="btn btn-success" disabled="@isProcessing">
                        @(isProcessing ? "Checking Availability..." : "Check Availability & Book")
                    </button>
                </div>
            </fieldset>
        }
    </EditForm>
}

@code {
    private AppointmentModel Model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isProcessing;
    private bool isSubmitted;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private async Task ProceedToStep2()
    {
        // Validate only step 1 fields (step 2 not yet active)
        Model.IsStep2Active = false;
        if (!editContext.Validate())
            return;

        showStep2 = true;
        Model.IsStep2Active = true;
    }

    private async Task OnDoctorChanged()
    {
        Model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        Model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task HandleSubmit()
    {
        Model.IsStep2Active = true;
        if (!editContext.Validate())
            return;

        isProcessing = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email!, Model.InsuranceProvider!, Model.Doctor!, Model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            isSubmitted = true;
        }
        finally
        {
            isProcessing = false;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        Model.IsStep2Active = false;
    }

    private void Reset()
    {
        Model = new();
        editContext = new EditContext(Model);
        showStep2 = false;
        isSubmitted = false;
        availableSlots = [];
    }
}

